import os
from pathlib import Path
import subprocess
import sys

JAVASCRIPT = "import { pathToFileURL } from 'node:url';\nimport path from 'node:path';\n\nconst root = process.argv[1];\nconst { createApplication } = await import(pathToFileURL(path.join(root, 'app.mjs')));\nconst equal = (left, right) => JSON.stringify(left) === JSON.stringify(right);\nconst count = value => Object.keys(value).length;\n\nfunction call(app, action, input = {}) {\n  const result = app.dispatch(action, input, 'admin');\n  if (!result.ok) throw new Error(`${action}: ${JSON.stringify(result)}`);\n  return result.data;\n}\n\nfunction source(documents, collections, origin = 'fixture:component') {\n  return { format: 'publication-exchange', version: 1, origin, collections, documents };\n}\n\nfunction fixture({ bound = false, policy = 'partial', independent = true } = {}) {\n  const app = createApplication();\n  const existing = call(app, 'collections.create', { name: 'Existing' });\n  const old = call(app, 'documents.create', { collectionId: existing.id, title: 'Existing B', body: 'Original B' });\n  const documents = [\n    { key: 'a', collectionKey: 'destination', title: 'A', body: '[B](exchange:b)' },\n    { key: 'b', collectionKey: 'destination', title: 'B', body: 'Replacement B' },\n  ];\n  if (independent) documents.push({ key: 'c', collectionKey: 'stable', title: 'C', body: 'Independent C' });\n  const collections = [{ key: 'destination', name: 'Imported manuals' }];\n  if (independent) collections.push({ key: 'stable', name: 'Existing' });\n  const request = { manifest: source(documents, collections), policy,\n    collectionBindings: { ...(bound ? { destination: existing.id } : {}),\n      ...(independent ? { stable: existing.id } : {}) },\n    targets: { b: { documentId: old.id,\n      expectedRevisionId: bound ? 'revision_9999' : old.revision.id } } };\n  return { app, existing, old, request };\n}\n\nfunction partialComponent({ bound, retry }) {\n  const { app, old, request } = fixture({ bound });\n  const before = app.inspect();\n  const plan = call(app, 'exchange.import.preview', request);\n  const previewNoMutation = equal(before, app.inspect());\n  const input = { ...request, planToken: plan.planToken, requestKey: 'partial-component' };\n  const receipt = call(app, 'exchange.import.apply', input);\n  const after = app.inspect();\n  const failedCollections = Object.values(after.collections).filter(item => item.name === 'Imported manuals');\n  const failedIds = new Set(failedCollections.map(item => item.id));\n  const observation = {\n    previewApplicable: plan.applicable, previewNoMutation,\n    predictedKeys: plan.imported.map(item => item.key),\n    rejectedKeys: receipt.rejected.map(item => item.key),\n    rejectionCodes: receipt.rejected.map(item => item.code),\n    receiptKeys: receipt.imported.map(item => item.key),\n    receiptCollectionKeys: Object.keys(receipt.collections).sort(),\n    remainingFailedCollectionCount: failedCollections.length,\n    remainingFailedMembershipCount: Object.values(after.memberships).filter(item => failedIds.has(item.collectionId)).length,\n    unexpectedFailedCollectionEvents: after.events.slice(before.events.length)\n      .filter(item => item.action === 'collection.created' && failedIds.has(item.target)).length,\n    retainedNewDocumentTitles: Object.values(after.documents).filter(item => !before.documents[item.id])\n      .map(item => after.revisions[item.currentRevisionId].title).sort(),\n    oldHistoryLength: call(app, 'documents.history', { id: old.id }).length,\n    deltas: Object.fromEntries(['collections', 'memberships', 'documents', 'revisions']\n      .map(key => [key, count(after[key]) - count(before[key])])),\n  };\n  observation.deltas.events = after.events.length - before.events.length;\n  observation.deltas.sequence = after.sequence - before.sequence;\n  const replay = call(app, 'exchange.import.apply', input);\n  observation.replayed = replay.replayed;\n  observation.replayUnchanged = equal(after, app.inspect());\n  observation.retry = null;\n  if (retry) {\n    const corrected = { policy: 'partial', manifest: source(request.manifest.documents.slice(0, 2),\n      [request.manifest.collections[0]]) };\n    const retryPlan = call(app, 'exchange.import.preview', corrected);\n    const retryBefore = app.inspect();\n    const retried = app.dispatch('exchange.import.apply', { ...corrected,\n      planToken: retryPlan.planToken, requestKey: 'corrected-component' }, 'admin');\n    observation.retry = {\n      previewApplicable: retryPlan.applicable,\n      previewDiagnostics: retryPlan.diagnostics.map(item => item.code),\n      code: retried.ok ? 'ok' : retried.error.code,\n      imported: retried.ok ? retried.data.imported.map(item => item.key) : [],\n      stateUnchangedOnFailure: retried.ok ? null : equal(retryBefore, app.inspect()),\n    };\n  }\n  return observation;\n}\n\nfunction failedBatch(policy, independent) {\n  const { app, request } = fixture({ policy, independent });\n  const before = app.inspect();\n  const plan = call(app, 'exchange.import.preview', request);\n  const previewNoMutation = equal(before, app.inspect());\n  const result = app.dispatch('exchange.import.apply', { ...request,\n    planToken: plan.planToken, requestKey: 'rejected-batch' }, 'admin');\n  return { previewNoMutation, previewApplicable: plan.applicable,\n    predictedKeys: plan.imported.map(item => item.key),\n    rejectedKeys: plan.rejected.map(item => item.key),\n    diagnostics: plan.diagnostics.map(item => item.code),\n    code: result.ok ? 'ok' : result.error.code,\n    stateUnchanged: equal(before, app.inspect()), receiptCount: count(app.inspect().exchangeReceipts) };\n}\n\nfunction orderedSuccess() {\n  const app = createApplication();\n  const request = { manifest: source([\n    { key: 'a', collectionKey: 'x', title: 'A', body: '[B](exchange:b)' },\n    { key: 'b', collectionKey: 'y', title: 'B', body: 'Second document' },\n  ], [{ key: 'x', name: 'X' }, { key: 'y', name: 'Y' }], 'fixture:order') };\n  const before = app.inspect();\n  const plan = call(app, 'exchange.import.preview', request);\n  const previewNoMutation = equal(before, app.inspect());\n  const input = { ...request, planToken: plan.planToken, requestKey: 'ordered' };\n  const receipt = call(app, 'exchange.import.apply', input);\n  const committed = app.inspect();\n  const replay = call(app, 'exchange.import.apply', input);\n  return {\n    previewNoMutation, importedKeys: receipt.imported.map(item => item.key),\n    events: committed.events.map(({ action, sequence, target }) => ({ action, sequence, target })),\n    documentSequences: Object.values(committed.documents).map(item => item.createdSequence),\n    revisionSequences: Object.values(committed.revisions).map(item => item.sequence),\n    bindings: receipt.collections,\n    firstBody: call(app, 'documents.get', { id: receipt.imported[0].documentId }).revision.body,\n    replayed: replay.replayed, replayUnchanged: equal(committed, app.inspect()),\n  };\n}\n\nfunction diagnosticPriority() {\n  const { app, existing, old } = fixture();\n  call(app, 'collections.create', { name: 'Taken' });\n  const request = { manifest: source([\n    { key: 'a', collectionKey: 'x', title: 'A', body: '[B](exchange:b)' },\n    { key: 'b', collectionKey: 'y', title: 'B', body: 'Later duplicate destination' },\n  ], [{ key: 'x', name: 'Existing' }, { key: 'y', name: 'Taken' }], 'fixture:priority'),\n  collectionBindings: { x: existing.id },\n  targets: { a: { documentId: old.id, expectedRevisionId: 'revision_9999' } } };\n  const before = app.inspect();\n  const plan = call(app, 'exchange.import.preview', request);\n  const result = app.dispatch('exchange.import.apply', { ...request,\n    planToken: plan.planToken, requestKey: 'priority' }, 'admin');\n  return { diagnostics: plan.diagnostics.map(item => item.code),\n    rejectedKeys: plan.rejected.map(item => item.key),\n    code: result.ok ? 'ok' : result.error.code, stateUnchanged: equal(before, app.inspect()) };\n}\n\nfunction synchronization() {\n  const app = createApplication();\n  const manifest = source([\n    { key: 'a', collectionKey: 'manual', title: 'A', body: '[B](exchange:b)' },\n    { key: 'b', collectionKey: 'manual', title: 'B', body: 'First B' },\n  ], [{ key: 'manual', name: 'Manual' }], 'fixture:sync');\n  const seedPlan = call(app, 'exchange.import.preview', { manifest });\n  const seeded = call(app, 'exchange.import.apply', { manifest,\n    planToken: seedPlan.planToken, requestKey: 'seed' });\n  const anchors = call(app, 'exchange.import.anchors', { id: seeded.id });\n  const changed = structuredClone(manifest);\n  changed.documents[1].body = 'Second B';\n  const request = { manifest: changed, anchors: anchors.anchors, collectionBindings: anchors.collectionBindings };\n  const before = app.inspect();\n  const plan = call(app, 'exchange.sync.preview', request);\n  const previewNoMutation = equal(before, app.inspect());\n  const input = { ...request, requestKey: 'incremental', planToken: plan.planToken,\n    expectedSourceIdentities: plan.sourceIdentities };\n  const receipt = call(app, 'exchange.sync.apply', input);\n  const committed = app.inspect();\n  const replay = call(app, 'exchange.sync.apply', input);\n  return { previewNoMutation, counts: plan.counts,\n    predictedKeys: plan.predicted.map(item => item.key),\n    importedKeys: receipt.imported.map(item => item.key), unchanged: receipt.unchanged,\n    firstHistoryLength: call(app, 'documents.history', { id: anchors.anchors.a.documentId }).length,\n    secondHistoryLength: call(app, 'documents.history', { id: anchors.anchors.b.documentId }).length,\n    secondBody: call(app, 'documents.get', { id: anchors.anchors.b.documentId }).revision.body,\n    replayed: replay.replayed, replayUnchanged: equal(committed, app.inspect()) };\n}\n\nfunction establishedCollections() {\n  const app = createApplication();\n  const request = { policy: 'partial', manifest: source([\n    { key: 'a', collectionKey: 'manual', title: 'A', body: 'Independent A' },\n    { key: 'b', collectionKey: 'manual', title: 'B', body: 'Independent B' },\n  ], [{ key: 'manual', name: 'Manual' }], 'fixture:sharing') };\n  const plan = call(app, 'exchange.import.preview', request);\n  const receipt = call(app, 'exchange.import.apply', { ...request,\n    planToken: plan.planToken, requestKey: 'shared' });\n  const state = app.inspect();\n  return { importedKeys: receipt.imported.map(item => item.key),\n    collectionCount: count(state.collections), membershipCount: count(state.memberships),\n    documentCount: count(state.documents),\n    sameCollection: new Set(receipt.imported.map(item => item.collectionId)).size === 1,\n    bindings: receipt.collections, events: state.events.map(item => item.action),\n    documentSequences: Object.values(state.documents).map(item => item.createdSequence),\n    revisionSequences: Object.values(state.revisions).map(item => item.sequence) };\n}\n\nprocess.stdout.write(JSON.stringify({\n  partialNewCollection: partialComponent({ bound: false, retry: true }),\n  boundCollectionFailure: partialComponent({ bound: true, retry: false }),\n  atomicFailure: failedBatch('atomic', true),\n  allFailedPartial: failedBatch('partial', false),\n  orderedSuccess: orderedSuccess(),\n  diagnosticPriority: diagnosticPriority(),\n  synchronization: synchronization(),\n  establishedCollections: establishedCollections(),\n}) + '\\n');\n"
root = Path(sys.argv[1]).resolve()
environment = {key: value for key, value in os.environ.items() if key not in ('NODE_OPTIONS', 'NODE_PATH')}
result = subprocess.run(['node', '--input-type=module', '-e', JAVASCRIPT, str(root)],
                        env=environment, capture_output=True, text=True, timeout=6)
sys.stdout.write(result.stdout)
sys.stderr.write(result.stderr)
sys.exit(result.returncode)
